#include <iostream>

long long toPiastres(long long pounds, long long piastres) {
    return pounds * 100 + piastres;
}

int main() {
    const long long lunch = toPiastres(32, 50);
    const long long snack = toPiastres(7, 50);
    std::cout << lunch + snack << '\n';
}

#include <iostream>
#include <vector>

int main() {
    std::vector<long long> amounts;
    amounts.push_back(3250);
    amounts.push_back(1200);
    amounts.push_back(750);

    long long total = 0;
    for (const long long amount : amounts) {
        total += amount;
    }

    std::cout << amounts.size() << " expenses\n";
    std::cout << total << " piastres\n";
}

#include <iostream>
#include <string>
#include <vector>

struct Expense {
    std::string category;
    long long amountPiastres;
};

int main() {
    const std::vector<Expense> expenses{
        {"food", 3250},
        {"transport", 1200},
        {"food", 750},
    };

    long long foodTotal = 0;
    for (const Expense& expense : expenses) {
        if (expense.category == "food") {
            foodTotal += expense.amountPiastres;
        }
    }
    std::cout << foodTotal << '\n';
}
